let html = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The Big CMS Game</title><style>
@import url('https://fonts.googleapis.com/css2?family=Archivo+Black&family=DM+Mono:wght@400;500&family=Manrope:wght@500;700;800&display=swap');
:root{--ink:#12142c;--lime:#d8ff4d;--pink:#ff4f9b;--sky:#63d9ff;--paper:#fff9e8;--purple:#7646ef}*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--paper);font-family:Manrope,Arial,sans-serif;min-height:100vh;overflow-x:hidden}body:before,body:after{content:'';position:fixed;border-radius:50%;z-index:-1}body:before{width:460px;height:460px;background:#4831a5;top:-220px;right:-120px}body:after{width:330px;height:330px;background:#dd397a;bottom:-160px;left:-130px}.wrap{width:min(760px,92vw);margin:auto;padding:34px 0 50px}.brand{text-align:center;font-family:'Archivo Black';line-height:.85;font-size:clamp(2.2rem,9vw,5.5rem);letter-spacing:-.07em;text-transform:uppercase;color:var(--lime);text-shadow:5px 5px 0 var(--pink)}.brand small{display:block;font-family:'DM Mono';font-size:.19em;letter-spacing:.25em;color:var(--paper);margin:15px 0 32px}.card{position:relative;background:var(--paper);color:var(--ink);border:4px solid var(--ink);box-shadow:9px 9px 0 var(--lime);border-radius:24px;padding:clamp(22px,6vw,46px)}h1{font-family:'Archivo Black';font-size:clamp(1.8rem,6vw,3.4rem);line-height:.95;letter-spacing:-.05em;margin:0 0 14px}p{font-size:1.05rem;line-height:1.45}.eyebrow,.count{font-family:'DM Mono';font-weight:500;text-transform:uppercase;letter-spacing:.08em}.count{display:inline-block;background:var(--sky);padding:9px 13px;border-radius:99px;font-size:.75rem;color:var(--ink)}input{display:block;width:100%;border:3px solid var(--ink);background:white;border-radius:13px;font:700 1.1rem Manrope;padding:15px;margin:22px 0 12px}input[type=number]{font-family:'Archivo Black';font-size:1.65rem;text-align:center}button{width:100%;border:3px solid var(--ink);background:var(--pink);color:#fff;padding:15px 18px;border-radius:13px;font:800 1rem Manrope;cursor:pointer;box-shadow:4px 4px 0 var(--ink);transition:.12s}button:active{transform:translate(3px,3px);box-shadow:1px 1px 0 var(--ink)}button:disabled{opacity:.55;cursor:not-allowed}button.alt{background:var(--lime);color:var(--ink)}button.option{color:var(--ink);text-align:center;margin:10px 0;font-size:1.08rem}.option.above{background:#ffb0d2}.option.below{background:#a7eaff}.option.exact{background:var(--lime)}.status{text-align:center;padding:16px;font-weight:800}.fun{font-family:'DM Mono';font-size:.82rem;color:#5b5671}.score{display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:2px dashed #d6cfbb}.score:first-child{border-top:2px dashed #d6cfbb}.score strong{font-family:'Archivo Black';font-size:1.4rem}.score small{display:block;font-family:'DM Mono';font-size:.72rem;color:#655f78;margin-top:2px}.hostbar{display:flex;gap:10px;margin-top:24px}.hostbar button{font-size:.8rem;padding:11px}.answers{font-family:'DM Mono';color:#514b65;margin-top:16px}.burst{font-size:3rem;position:absolute;transform:rotate(-12deg);right:22px;top:18px}.footer{text-align:center;color:#b8b4cb;font-family:'DM Mono';font-size:.72rem;margin-top:25px}.timer{position:absolute;right:20px;top:20px;width:62px;height:62px;border:4px solid var(--ink);border-radius:50%;display:grid;place-items:center;background:var(--lime);font-family:'Archivo Black';font-size:1.35rem;box-shadow:4px 4px 0 var(--pink)}.timer.danger{background:var(--pink);color:#fff;animation:pulse .65s infinite alternate}.hero-number{font-family:'Archivo Black';font-size:clamp(3rem,15vw,6.5rem);line-height:1;text-align:center;color:var(--purple);text-shadow:4px 4px 0 var(--lime);margin:24px 0}.player-chip{display:inline-block;background:var(--ink);color:#fff;border-radius:99px;padding:9px 14px;font-weight:800}.result{background:#eee6ff;border:3px solid var(--ink);border-radius:16px;padding:18px;margin:18px 0}.result strong{font-family:'Archivo Black';font-size:1.35rem}.vote-grid{display:grid;grid-template-columns:1fr;gap:3px}.mini-points{font-family:'DM Mono';font-size:.82rem;color:#514b65}.waiting{text-align:center;padding:22px 5px}.waiting .emoji{font-size:3.2rem;display:block;animation:float 1.2s ease-in-out infinite alternate}@keyframes pulse{to{transform:scale(1.08)}}@keyframes float{to{transform:translateY(-8px) rotate(5deg)}}@media(min-width:700px){.hostbar button{width:auto;flex:1}.vote-grid{grid-template-columns:repeat(3,1fr);gap:10px}}
@media(max-width:699px){body:not(.host){height:100dvh;min-height:100dvh;overflow:hidden;overscroll-behavior:none}body:not(.host) .wrap{width:min(94vw,480px);height:100dvh;padding:10px 0 8px;display:flex;flex-direction:column}body:not(.host) .brand{flex:0 0 auto;font-size:clamp(1.55rem,8vw,2.2rem);line-height:.76;text-shadow:3px 3px 0 var(--pink)}body:not(.host) .brand small{font-size:.18em;margin:6px 0 9px}body:not(.host) .card{flex:1;min-height:0;padding:14px 14px 12px;border-width:3px;box-shadow:5px 5px 0 var(--lime);overflow:auto;display:flex;flex-direction:column;justify-content:center}body:not(.host) .footer{display:none}body:not(.host) h1{font-size:clamp(1.3rem,6.2vw,2rem);line-height:1;margin:0 50px 8px 0}body:not(.host) p{font-size:1rem;line-height:1.25;margin:7px 0}body:not(.host) .eyebrow,body:not(.host) .count{font-size:.72rem}body:not(.host) input{padding:12px;margin:9px 0 8px;font-size:1rem}body:not(.host) input[type=number]{font-size:1.35rem}body:not(.host) button{padding:12px 8px}body:not(.host) .timer{width:44px;height:44px;right:11px;top:11px;border-width:3px;font-size:1rem;box-shadow:3px 3px 0 var(--pink)}body:not(.host) .hero-number{font-size:clamp(2.4rem,14vw,4rem);margin:8px 0}body:not(.host) .waiting{padding:8px 3px}body:not(.host) .waiting .emoji{font-size:2rem}body:not(.host) .result{padding:10px;margin:8px 0}body:not(.host) .score{padding:6px 0}body:not(.host) .score strong{font-size:1.05rem}body:not(.host) .answers{margin-top:8px;font-size:.75rem}body:not(.host) .vote-grid{grid-template-columns:repeat(3,1fr);gap:6px}body:not(.host) button.option{margin:0;font-size:.78rem}body:not(.host) .fun{font-size:.75rem}body:not(.host) .burst{font-size:2rem;right:10px;top:8px}}
@media(max-width:699px){body:not(.host)[data-phase=reveal] .wrap{padding:6px 0}body:not(.host)[data-phase=reveal] .brand{display:none}body:not(.host)[data-phase=reveal] .card{justify-content:flex-start;padding:10px 12px}body:not(.host)[data-phase=reveal] h1{font-size:1.1rem;line-height:1.05;margin:0 30px 5px 0}body:not(.host)[data-phase=reveal] .result{margin:5px 0;padding:8px 10px}body:not(.host)[data-phase=reveal] .result strong{font-size:1.15rem}body:not(.host)[data-phase=reveal] .result small{display:block;font-family:'DM Mono';font-size:.7rem;margin-top:3px;color:#514b65}body:not(.host)[data-phase=reveal] .fun,body:not(.host)[data-phase=reveal] .mini-points{margin:4px 0;font-size:.72rem}body:not(.host)[data-phase=reveal] .score{padding:4px 0}body:not(.host)[data-phase=reveal] .score small{font-size:.66rem}}
@media(max-width:900px) and (max-height:520px){body:not(.host){height:100dvh;overflow:hidden}body:not(.host) .wrap{width:96vw;height:100dvh;padding:5px 0}body:not(.host) .brand,body:not(.host) .footer{display:none}body:not(.host) .card{height:100%;padding:10px 14px;overflow:auto}body:not(.host) h1{font-size:1.2rem;margin-bottom:5px}body:not(.host) p{margin:4px 0}body:not(.host) .hero-number{font-size:2.5rem;margin:4px 0}}
</style></head><body><main class="wrap"><div class="brand">THE BIG<br>CMS GAME<small>o quiz que ninguém pediu, mas todos vão ganhar</small></div><section class="card" id="app"><div class="status">Carregando a diversão...</div></section><div class="footer">feito para pessoas brilhantes · chutes sem calculadora, por favor</div></main>
<script>
const app=document.getElementById('app');let me=localStorage.cmsPlayer||'',host=location.hash==='#host'||new URLSearchParams(location.search).get('host')==='1',state=null,draftName=localStorage.cmsName||'',draftGuess='',draftGuessQuestion=null,timerHandle;document.body.classList.toggle('host',host);
const esc=s=>String(s??'').replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[m]));
async function api(path,method='GET',body){let r=await fetch('/api/'+path,{method,headers:{'content-type':'application/json'},body:body?JSON.stringify(body):undefined}),data=await r.json();if(!r.ok)throw new Error(data.error||'Algo deu ruim');return data}
function hostControls(label){if(!host)return '';return '<div class="hostbar">'+(label?'<button class="alt" id="hostAction">'+label+'</button>':'')+'<button id="reset">Recomeçar</button></div>'}
function bindHost(){if(!host)return;let a=document.getElementById('hostAction'),r=document.getElementById('reset');if(a)a.onclick=async()=>{a.disabled=true;a.textContent='Só um segundo…';try{let x=await api('host/next','POST');state=x.state;render()}catch(e){a.disabled=false;a.textContent='Tentar novamente'}};if(r)r.onclick=async()=>{r.disabled=true;await api('host/reset','POST');await tick()}}
function timer(){clearInterval(timerHandle);if(!state.deadlineAt)return;let draw=()=>{let left=Math.max(0,Math.ceil((state.deadlineAt-(Date.now()+(state.clockOffset||0)))/1000)),el=document.getElementById('timer');if(el){el.textContent=left;el.classList.toggle('danger',left<=5)}if(left<=0){clearInterval(timerHandle);api('timeout','POST').then(x=>{state=x.state;render()}).catch(()=>setTimeout(tick,500))}};draw();timerHandle=setInterval(draw,250)}
function lobby(){if(host){app.innerHTML='<div class="burst">✦</div><span class="eyebrow">tela do host</span><h1>Todo mundo na sala?</h1><p>Os jogadores entram pelo link no celular. Quando estiverem prontos, comece o jogo.</p><div class="count">'+state.players.length+' pessoa'+(state.players.length===1?'':'s')+' na sala</div><div>'+state.players.map(x=>'<div class="score"><span>'+esc(x.name)+'</span><strong>✓</strong></div>').join('')+'</div>'+hostControls('Começar jogo');bindHost();return}app.innerHTML='<div class="burst">✦</div><span class="eyebrow">sala de espera</span><h1>Chegue chegando.</h1><p>Escolha seu nome de guerra.</p><div class="count">'+state.players.length+' pessoa'+(state.players.length===1?'':'s')+' na sala</div><input id="name" maxlength="24" placeholder="Ex.: Rainha do Briefing" value="'+esc(draftName)+'"><button id="join">'+(me?'Atualizar meu nome':'Entrar no jogo →')+'</button><p class="fun">'+(me?'Você já está na sala. Agora é só esperar o host começar.':'Você pode inventar um nome. Só não use o do chefe… ou use.')+'</p>';document.getElementById('name').oninput=e=>draftName=e.target.value;document.getElementById('join').onclick=async()=>{let n=document.getElementById('name').value.trim();if(!n)return;let x=await api('join','POST',{name:n,existing:me});me=x.id;localStorage.cmsPlayer=me;localStorage.cmsName=n;await tick()}}
function roundHeader(){return '<div class="timer" id="timer">'+(state.questionIndex===0?40:20)+'</div><span class="eyebrow">rodada '+(state.questionIndex+1)+' de '+state.totalQuestions+'</span><h1>'+esc(state.question.question)+'</h1>'}
function guess(){let mine=!host&&me===state.guesser.id,content;if(mine&&draftGuessQuestion!==state.questionIndex){draftGuessQuestion=state.questionIndex;draftGuess=''}if(host)content='<p>É a vez de <span class="player-chip">'+esc(state.guesser.name)+'</span></p><div class="waiting"><span class="emoji">🧠</span><strong>'+esc(state.guesser.name)+'</strong> está estimando um número no celular…</div>';else if(mine)content='<p>É a sua vez. Estime a resposta em números.</p><input id="guess" type="number" inputmode="decimal" step="any" placeholder="Seu palpite" value="'+esc(draftGuess)+'"><button id="sendGuess">Enviar meu palpite →</button>';else content='<p>É a vez de <span class="player-chip">'+esc(state.guesser.name)+'</span></p><div class="waiting"><span class="emoji">🧠</span>Aguarde o palpite aparecer na TV.</div>';app.innerHTML=roundHeader()+content+hostControls('Encerrar tempo');if(mine){let input=document.getElementById('guess');input.oninput=e=>draftGuess=e.target.value;document.getElementById('sendGuess').onclick=async()=>{let value=Number(input.value);if(!Number.isFinite(value))return;let b=document.getElementById('sendGuess');b.disabled=true;b.textContent='Palpite enviado!';try{let x=await api('guess','POST',{playerId:me,value});draftGuess='';state=x.state;render()}catch(e){b.disabled=false;b.textContent=e.message}}}bindHost();timer()}
function vote(){let isGuesser=!host&&me===state.guesser.id,answered=!host&&state.answers.includes(me),prompt='<p>A resposta verdadeira está <b>acima</b>, <b>abaixo</b> ou é <b>exatamente igual</b> a esse número?</p>',response='<p><span class="player-chip">'+esc(state.guesser.name)+'</span> respondeu:</p><div class="hero-number">'+esc(state.guessDisplay)+'</div>',content;if(host)content=response+prompt+'<div class="answers">'+state.answerCount+' de '+state.eligibleVoters+' votos entregues</div>';else if(isGuesser)content='<p>Seu palpite apareceu na TV:</p><div class="hero-number">'+esc(state.guessDisplay)+'</div><div class="waiting"><span class="emoji">😬</span>Agora aguente o julgamento coletivo.</div>';else if(answered)content=response+'<div class="waiting"><span class="emoji">✅</span>Voto entregue. Aguarde a revelação.</div>';else if(me)content=response+prompt+'<div class="vote-grid"><button class="option above" data-v="above">⬆ ACIMA</button><button class="option below" data-v="below">⬇ ABAIXO</button><button class="option exact" data-v="exact">🎯 EXATO</button></div>';else content='<div class="waiting"><span class="emoji">📱</span>Entre no jogo pelo celular para votar.</div>';app.innerHTML=roundHeader()+content+hostControls('Revelar agora');if(!isGuesser&&!answered&&me&&!host)document.querySelectorAll('[data-v]').forEach(b=>b.onclick=async()=>{document.querySelectorAll('[data-v]').forEach(x=>x.disabled=true);let x=await api('vote','POST',{playerId:me,vote:b.dataset.v});state=x.state;render()});bindHost();timer()}
function reveal(){let mine=state.roundPoints.find(x=>x.id===me),board='<p class="eyebrow">Placar após esta rodada</p><div>'+state.roundPoints.map((x,i)=>'<div class="score"><span><b>#'+(i+1)+' '+esc(x.name)+'</b><small>+'+x.points+' nesta rodada</small></span><strong>'+x.score+' pts</strong></div>').join('')+'</div>';if(host)app.innerHTML='<div class="burst">💥</div><span class="eyebrow">a verdade apareceu</span><h1>'+esc(state.question.question)+'</h1><div class="result">Resposta certa<br><strong>'+esc(state.answerDisplay)+'</strong></div><p><span class="player-chip">'+esc(state.guesser.name)+'</span> chutou <b>'+esc(state.guessDisplay||'nada')+'</b>.</p><div class="hero-number">'+state.guessPoints+' pts</div><p class="fun">'+esc(state.question.fact)+'</p>'+board+hostControls(state.questionIndex+1<state.totalQuestions?'Próxima pergunta':'Ver placar final');else app.innerHTML='<div class="burst">💥</div><span class="eyebrow">resultado</span><h1>'+esc(state.question.question)+'</h1><div class="result">Resposta: <strong>'+esc(state.answerDisplay)+'</strong><small>Palpite de '+esc(state.guesser.name)+': '+esc(state.guessDisplay||'nada')+' · +'+state.guessPoints+' pts</small></div><p class="fun">'+esc(state.question.fact)+'</p>'+(mine?'<p class="mini-points">Você ganhou <b>'+mine.points+' pontos</b> nesta rodada.</p>':'')+board;bindHost()}
function scores(){let mine=state.scores.find(x=>x.id===me);app.innerHTML='<div class="burst">★</div><span class="eyebrow">placar final</span><h1>Fim de jogo!</h1><p>'+(mine?'Você ficou com <b>'+mine.score+' pontos</b>. '+(mine.rank===1?'Lenda absoluta.':'Uma trajetória respeitável.'):'O júri chegou ao veredito.')+'</p><div>'+state.scores.map((x,i)=>'<div class="score"><span>'+(i===0?'👑 ':'')+esc(x.name)+'</span><strong>'+x.score+'</strong></div>').join('')+'</div>'+hostControls(null);bindHost()}
function render(){clearInterval(timerHandle);document.body.dataset.phase=state.phase;if(state.phase==='lobby')lobby();else if(state.phase==='guess')guess();else if(state.phase==='vote')vote();else if(state.phase==='reveal')reveal();else scores()}
async function tick(){let next=await api('state');next.clockOffset=next.serverNow-Date.now();state=next;render()}tick();
let realtimeRetry;function connectRealtime(){clearTimeout(realtimeRetry);const protocol=location.protocol==='https:'?'wss':'ws',socket=new WebSocket(protocol+'://'+location.host+'/api/ws');let syncTimer;socket.onopen=()=>syncTimer=setInterval(()=>{if(socket.readyState===WebSocket.OPEN)socket.send('sync')},700);socket.onmessage=e=>{try{if(JSON.parse(e.data).type==='state-changed')tick()}catch{}};socket.onclose=()=>{clearInterval(syncTimer);realtimeRetry=setTimeout(connectRealtime,1500)};socket.onerror=()=>socket.close()}connectRealtime();setInterval(tick,10000);
</script></body></html>`;

function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json','cache-control':'no-store'}})}
let schemaReady;
async function ensure(db){if(!schemaReady)schemaReady=(async()=>{await db.batch([
  db.prepare("CREATE TABLE IF NOT EXISTS game_state (id INTEGER PRIMARY KEY CHECK (id = 1), phase TEXT NOT NULL DEFAULT 'lobby', question_index INTEGER NOT NULL DEFAULT 0, round_id INTEGER NOT NULL DEFAULT 0)"),
  db.prepare('CREATE TABLE IF NOT EXISTS game_questions (position INTEGER PRIMARY KEY, question_key TEXT NOT NULL)'),
  db.prepare('CREATE TABLE IF NOT EXISTS players (id TEXT PRIMARY KEY, name TEXT NOT NULL, score INTEGER NOT NULL DEFAULT 0, joined_at INTEGER NOT NULL)'),
  db.prepare('CREATE TABLE IF NOT EXISTS answers (player_id TEXT NOT NULL, round_id INTEGER NOT NULL, option_index INTEGER NOT NULL, answered_at INTEGER NOT NULL, PRIMARY KEY (player_id, round_id))'),
  db.prepare('CREATE TABLE IF NOT EXISTS numeric_rounds (round_id INTEGER PRIMARY KEY, question_index INTEGER NOT NULL, guesser_id TEXT NOT NULL, guess_value REAL, deadline_at INTEGER NOT NULL, finalized INTEGER NOT NULL DEFAULT 0, guess_points INTEGER NOT NULL DEFAULT 0)'),
  db.prepare("CREATE TABLE IF NOT EXISTS numeric_answers (player_id TEXT NOT NULL, round_id INTEGER NOT NULL, role TEXT NOT NULL, value TEXT NOT NULL, answered_at INTEGER NOT NULL, points INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (player_id, round_id))"),
  db.prepare("INSERT OR IGNORE INTO game_state (id,phase,question_index,round_id) VALUES (1,'lobby',0,0)")
]);await db.prepare("UPDATE game_state SET phase='lobby',question_index=0,round_id=0 WHERE phase NOT IN ('lobby','guess','vote','reveal','scores')").run()})().catch(e=>{schemaReady=null;throw e});await schemaReady}
const formatNumber=n=>Number(n).toLocaleString('pt-BR',{maximumFractionDigits:2});
const relativeError=(guess,answer)=>Math.abs(guess-answer)/Math.max(Math.abs(answer),1);
const direction=(guess,answer)=>guess===answer?'exact':answer>guess?'above':'below';
const guessScore=(guess,answer)=>Math.max(0,Math.round(3000*(1-relativeError(guess,answer)/.30)));
const shuffle=items=>{let result=[...items];for(let i=result.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result};
async function getQuestion(db,index){let row=await db.prepare('SELECT question_key FROM game_questions WHERE position=?').bind(index).first();return questionByKey.get(row?.question_key)||allQuestions[index]}
async function questionCount(db){let row=await db.prepare('SELECT COUNT(*) AS count FROM game_questions').first();return Number(row?.count||0)}
async function prepareQuestionOrder(db,playerCount){let roundCount=Math.max(requiredQuestions.length,Math.min(playerCount,allQuestions.length)),reserveCount=roundCount-requiredQuestions.length,requiredOrder=['cms-csat','chatarco-personas','cms-delays','private-school','item-cost','pisa-rank','cms-people','chatarco-messages','cross-bank','enem','cms-projects','chatarco-users','page-hours'],extras=shuffle(reserveQuestions).slice(0,reserveCount).map(q=>q.key),order=[];for(let i=0;i<requiredOrder.length;i++){order.push(requiredOrder[i]);let target=Math.round((i+1)*reserveCount/requiredOrder.length),inserted=order.length-(i+1);while(inserted<target){order.push(extras.shift());inserted++}}await db.prepare('DELETE FROM game_questions').run();if(order.length)await db.batch(order.map((key,position)=>db.prepare('INSERT INTO game_questions (position,question_key) VALUES (?,?)').bind(position,key)));return order.length}
async function finalizeRound(db,g,round){if(!round||round.finalized)return;let claim=await db.prepare('UPDATE numeric_rounds SET finalized=1 WHERE round_id=? AND finalized=0').bind(g.round_id).run();if(!claim.meta?.changes)return;let q=await getQuestion(db,g.question_index),guess=round.guess_value,updates=[];if(guess!==null&&guess!==undefined){let numericGuess=Number(guess),gp=guessScore(numericGuess,q.answer);updates.push(db.prepare('UPDATE players SET score=score+? WHERE id=?').bind(gp,round.guesser_id));let votes=(await db.prepare("SELECT player_id,value FROM numeric_answers WHERE round_id=? AND role='vote'").bind(g.round_id).all()).results,exact=relativeError(numericGuess,q.answer)<=.01,correctDirection=direction(numericGuess,q.answer);for(let v of votes){let points=v.value==='exact'&&exact?3000:(v.value===correctDirection&&correctDirection!=='exact'?1000:0);updates.push(db.prepare('UPDATE numeric_answers SET points=? WHERE player_id=? AND round_id=?').bind(points,v.player_id,g.round_id));if(points)updates.push(db.prepare('UPDATE players SET score=score+? WHERE id=?').bind(points,v.player_id))}updates.push(db.prepare('UPDATE numeric_rounds SET guess_points=? WHERE round_id=?').bind(gp,g.round_id))}else updates.push(db.prepare('UPDATE numeric_rounds SET guess_points=0 WHERE round_id=?').bind(g.round_id));updates.push(db.prepare("UPDATE game_state SET phase='reveal' WHERE id=1"));await db.batch(updates)}
async function expire(db){let g=await db.prepare('SELECT phase,question_index,round_id FROM game_state WHERE id=1').first();if(!['guess','vote'].includes(g.phase))return g;let round=await db.prepare('SELECT * FROM numeric_rounds WHERE round_id=?').bind(g.round_id).first();if(round&&Date.now()>=round.deadline_at){if(g.phase==='guess')await db.batch([db.prepare('UPDATE numeric_rounds SET finalized=1,guess_points=0 WHERE round_id=?').bind(g.round_id),db.prepare("UPDATE game_state SET phase='reveal' WHERE id=1")]);else await finalizeRound(db,g,round);g=await db.prepare('SELECT phase,question_index,round_id FROM game_state WHERE id=1').first()}return g}
async function snapshot(db){let g=await expire(db),players=(await db.prepare('SELECT id,name,score FROM players ORDER BY joined_at').all()).results,total=await questionCount(db),projected=Math.max(requiredQuestions.length,Math.min(players.length,allQuestions.length)),base={phase:g.phase,questionIndex:g.question_index,totalQuestions:total||projected,players,serverNow:Date.now()};if(g.phase==='lobby')return base;if(g.phase==='scores'){base.scores=(await db.prepare('SELECT id,name,score FROM players ORDER BY score DESC,joined_at ASC').all()).results.map((x,i)=>({...x,rank:i+1}));return base}let round=await db.prepare('SELECT * FROM numeric_rounds WHERE round_id=?').bind(g.round_id).first(),q=await getQuestion(db,g.question_index),guesser=players.find(x=>x.id===round.guesser_id)||{id:round.guesser_id,name:'Jogador misterioso'},display=n=>(q.prefix||'')+formatNumber(n)+(q.suffix||'');Object.assign(base,{question:{question:q.question,fact:q.fact},guesser,deadlineAt:['guess','vote'].includes(g.phase)?round.deadline_at:null,guessDisplay:round.guess_value===null?null:display(round.guess_value),answerCount:0,eligibleVoters:Math.max(0,players.length-1),answers:[]});if(g.phase==='vote'){let votes=(await db.prepare("SELECT player_id FROM numeric_answers WHERE round_id=? AND role='vote'").bind(g.round_id).all()).results;base.answers=votes.map(x=>x.player_id);base.answerCount=votes.length}if(g.phase==='reveal'){base.answerDisplay=display(q.answer);base.guessPoints=round.guess_points;base.roundPoints=(await db.prepare("SELECT p.id,p.name,p.score,CASE WHEN p.id=? THEN ? ELSE COALESCE(a.points,0) END AS points FROM players p LEFT JOIN numeric_answers a ON a.player_id=p.id AND a.round_id=? AND a.role='vote' ORDER BY p.score DESC,p.joined_at ASC").bind(round.guesser_id,round.guess_points,g.round_id).all()).results}return base}
async function startRound(db,index,roundId){let players=(await db.prepare('SELECT id FROM players ORDER BY joined_at').all()).results;if(!players.length)throw new Error('Nenhum jogador na sala');let guesser=players[index%players.length].id;await db.batch([db.prepare('INSERT OR REPLACE INTO numeric_rounds (round_id,question_index,guesser_id,guess_value,deadline_at,finalized,guess_points) VALUES (?,?,?,?,?,0,0)').bind(roundId,index,guesser,null,Date.now()+roundSeconds(index)*1000),db.prepare("UPDATE game_state SET phase='guess',question_index=?,round_id=? WHERE id=1").bind(index,roundId)])}
export default {async fetch(req,env){let url=new URL(req.url);if(!url.pathname.startsWith('/api/'))return new Response(html,{headers:{'content-type':'text/html;charset=UTF-8','cache-control':'no-store'}});let path=url.pathname.slice(5),db=env.DB;await ensure(db);if(req.method==='GET'&&path==='state')return json(await snapshot(db));let body={};try{body=await req.json()}catch{}
if(path==='join'&&req.method==='POST'){let name=String(body.name||'').trim().slice(0,24);if(!name)return json({error:'Nome obrigatório'},400);let id=body.existing||crypto.randomUUID(),exists=await db.prepare('SELECT id FROM players WHERE id=?').bind(id).first();if(!exists)await db.prepare('INSERT INTO players (id,name,score,joined_at) VALUES (?,?,0,?)').bind(id,name,Date.now()).run();else await db.prepare('UPDATE players SET name=? WHERE id=?').bind(name,id).run();return json({id})}
if(path==='guess'&&req.method==='POST'){let g=await expire(db),round=await db.prepare('SELECT * FROM numeric_rounds WHERE round_id=?').bind(g.round_id).first(),id=String(body.playerId||''),value=Number(body.value);if(g.phase!=='guess'||id!==round?.guesser_id||!Number.isFinite(value)||Date.now()>=round.deadline_at)return json({error:'Tempo encerrado'},400);await db.batch([db.prepare("INSERT OR REPLACE INTO numeric_answers (player_id,round_id,role,value,answered_at,points) VALUES (?,?,'guess',?,?,0)").bind(id,g.round_id,String(value),Date.now()),db.prepare('UPDATE numeric_rounds SET guess_value=?,deadline_at=? WHERE round_id=?').bind(value,Date.now()+roundSeconds(g.question_index)*1000,g.round_id),db.prepare("UPDATE game_state SET phase='vote' WHERE id=1")]);let total=(await db.prepare('SELECT COUNT(*) AS count FROM players').first()).count;if(total<=1){g=await db.prepare('SELECT phase,question_index,round_id FROM game_state WHERE id=1').first();round=await db.prepare('SELECT * FROM numeric_rounds WHERE round_id=?').bind(g.round_id).first();await finalizeRound(db,g,round)}return json({ok:true,state:await snapshot(db)})}
if(path==='vote'&&req.method==='POST'){let g=await expire(db),round=await db.prepare('SELECT * FROM numeric_rounds WHERE round_id=?').bind(g.round_id).first(),id=String(body.playerId||''),vote=String(body.vote||'');if(g.phase!=='vote'||id===round?.guesser_id||!['above','below','exact'].includes(vote)||Date.now()>=round.deadline_at)return json({error:'Voto indisponível'},400);let player=await db.prepare('SELECT id FROM players WHERE id=?').bind(id).first();if(!player)return json({error:'Jogador não encontrado'},404);await db.prepare("INSERT OR IGNORE INTO numeric_answers (player_id,round_id,role,value,answered_at,points) VALUES (?,?,'vote',?,?,0)").bind(id,g.round_id,vote,Date.now()).run();let counts=await db.prepare("SELECT (SELECT COUNT(*) FROM numeric_answers WHERE round_id=? AND role='vote') AS votes,(SELECT COUNT(*) FROM players) AS players").bind(g.round_id).first();if(counts.votes>=counts.players-1){round=await db.prepare('SELECT * FROM numeric_rounds WHERE round_id=?').bind(g.round_id).first();await finalizeRound(db,g,round)}return json({ok:true,state:await snapshot(db)})}
if(path==='timeout'&&req.method==='POST'){await expire(db);return json({ok:true,state:await snapshot(db)})}
if(path==='host/next'&&req.method==='POST'){let g=await db.prepare('SELECT phase,question_index,round_id FROM game_state WHERE id=1').first();try{if(g.phase==='lobby'){let total=(await db.prepare('SELECT COUNT(*) AS count FROM players').first()).count;await prepareQuestionOrder(db,Number(total));await startRound(db,0,1)}else if(g.phase==='guess')await db.batch([db.prepare('UPDATE numeric_rounds SET finalized=1,guess_points=0 WHERE round_id=?').bind(g.round_id),db.prepare("UPDATE game_state SET phase='reveal' WHERE id=1")]);else if(g.phase==='vote'){let round=await db.prepare('SELECT * FROM numeric_rounds WHERE round_id=?').bind(g.round_id).first();await finalizeRound(db,g,round)}else if(g.phase==='reveal'&&g.question_index<(await questionCount(db))-1)await startRound(db,g.question_index+1,g.round_id+1);else if(g.phase==='reveal')await db.prepare("UPDATE game_state SET phase='scores' WHERE id=1").run()}catch(e){return json({error:e.message},400)}return json({ok:true,state:await snapshot(db)})}
if(path==='host/reset'&&req.method==='POST'){await db.batch([db.prepare('DELETE FROM numeric_answers'),db.prepare('DELETE FROM numeric_rounds'),db.prepare('DELETE FROM answers'),db.prepare('DELETE FROM game_questions'),db.prepare('DELETE FROM players'),db.prepare("UPDATE game_state SET phase='lobby',question_index=0,round_id=0 WHERE id=1")]);return json({ok:true,state:await snapshot(db)})}
return json({error:'Não encontrado'},404)}};
